static __forceinline void orient_previous_pair_with_up(
    Path* path,
    int current_index,
    int curve_index,
    PathTemplateSample* roll_source)
{
    if (curve_index == 0) {
        path->primary_samples[current_index - 1].transform.RotIdentity();
        path->secondary_samples[current_index - 1].transform.RotIdentity();
        return;
    }
    orient_previous_with_up(
        path->primary_samples, current_index, curve_index, roll_source);
    orient_previous_with_up(
        path->secondary_samples, current_index, curve_index, roll_source);
}

