static __forceinline void orient_previous_pair_with_up(
    PathTemplateSample* primary,
    PathTemplateSample* secondary,
    int current_index,
    int curve_index,
    PathTemplateSample* roll_source)
{
    if (curve_index != 0) {
        orient_previous_with_up(
            primary, current_index, curve_index, roll_source);
        orient_previous_with_up(
            secondary, current_index, curve_index, roll_source);
    } else {
        primary[current_index - 1].transform.RotIdentity();
        secondary[current_index - 1].transform.RotIdentity();
    }
}

